// app/layout.tsx
import { Inter } from 'next/font/google';

// 1. Configure the font. 
// subsets optimize the file size by only including specific alphabets (like Latin).
const inter = Inter({
  subsets: ['latin'],
  display: 'swap', 
});

export default function RootLayout({ children }) {
  return (
    <html lang="en">
      {/* 2. Apply the magic generated className to the body */}
      <body className={inter.className}>
        {children}
      </body>
    </html>
  );
}
